  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."inbox"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('integer') THEN
    missing := missing || E'\n  ' || 'line 29: app.inbox.id is ' || v_type
      || ', not integer: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."feedback"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('integer') THEN
    missing := missing || E'\n  ' || 'line 34: app.feedback.id is ' || v_type
      || ', not integer: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT atttypid, replace(format_type(atttypid, NULL), 'character varying', 'varchar') INTO v_oid, v_type
  FROM pg_attribute WHERE attrelid = to_regclass('"app"."folders"') AND attname = 'id' AND attnum > 0 AND NOT attisdropped;
  IF FOUND AND v_oid <> to_regtype('integer') THEN
    missing := missing || E'\n  ' || 'line 40: app.folders.id is ' || v_type
      || ', not integer: write its type after the key, (id ' || v_type || ') [AZ602]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'user'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 8: ' || v_n || ' shares of user name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'service'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 10: ' || v_n || ' shares of service name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'project'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 12: ' || v_n || ' shares of project name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'note'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 22: ' || v_n || ' shares of note name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'message'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 29: ' || v_n || ' shares of message name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'feedback'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 34: ' || v_n || ' shares of feedback name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  SELECT count(*) INTO v_n FROM authz.shares g WHERE g.object_type = 'folder'
    AND NOT pg_catalog.pg_input_is_valid(g.object_id, 'integer');
  IF v_n > 0 THEN
    missing := missing || E'\n  ' || 'line 40: ' || v_n || ' shares of folder name ids a integer can''t read (their rows are gone): delete them first, as rowstile help AZ627 says [AZ627]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7', anyone's -> '*' (invalid ids
-- as they are)
CREATE OR REPLACE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'service' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'project' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'note' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'message' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'feedback' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'folder' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'integer') THEN RETURN p_id::integer::text; END IF;
    WHEN 'anyone' THEN RETURN '*';  -- one subject, whatever id names it
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;

-- shares written directly get canonical ids too
CREATE OR REPLACE FUNCTION authz_int.shares_canon() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  NEW.object_id := authz_int.canon(NEW.object_type, NEW.object_id);
  NEW.subject_id := authz_int.canon(NEW.subject_type, NEW.subject_id);
  IF NEW.subject_type = 'anyone' THEN NEW.subject_relation := ''; END IF;
  RETURN NEW;
END $f$;

CREATE TRIGGER authz_shares_canon BEFORE INSERT OR UPDATE OF object_type, object_id, subject_type, subject_id,
  subject_relation ON authz.shares FOR EACH ROW EXECUTE FUNCTION authz_int.shares_canon();

-- Inheritance tables kept whose tables have other tables under them since they were computed (a partition
-- attached or detached: no trigger saw those rows) are computed again
DO $stale$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;
  FOR r IN SELECT n.name, n.oids, n.fn FROM (VALUES ('folder__parent__tree', ARRAY[to_regclass('"app"."folders"')::oid]::oid[] || ARRAY(WITH RECURSIVE below(oid) AS (
    SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = ANY (ARRAY[to_regclass('"app"."folders"')::oid]::oid[])
    UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN below b ON i.inhparent = b.oid)
  SELECT b.oid FROM below b ORDER BY b.oid), 'authz_int."folder__parent__tree_rebuild"()')) n(name, oids, fn)
           JOIN authz_int.trees t ON t.name = n.name
           WHERE t.oids IS DISTINCT FROM n.oids AND to_regprocedure(n.fn) IS NOT NULL LOOP
    EXECUTE format('SELECT %s', r.fn);
    UPDATE authz_int.trees SET oids = r.oids WHERE name = r.name;
  END LOOP;
END $stale$;

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND c.relname LIKE 'shares\_obj\_%'
             AND c.relname <> ALL (ARRAY['shares_obj_user_integer', 'shares_obj_service_integer', 'shares_obj_project_integer', 'shares_obj_note_integer', 'shares_obj_message_integer', 'shares_obj_feedback_integer', 'shares_obj_folder_integer']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
